insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_145'
from (values
('127.889.d.17.A',3,'A mechanic pulls a spark plug, cleans the electrodes, checks the gap and torques it back in. She is:','["removing, cleaning, inspecting and installing a spark plug", "painting a spark plug", "ignoring a spark plug", "buying a spark plug"]'::jsonb,0,'Plug service.','original'),
('127.889.d.17.A',4,'Before reinstalling a cleaned spark plug, the mechanic should verify the:','["paint color", "electrode gap", "seat fit", "tire size"]'::jsonb,1,'Gap check.','original'),
('127.889.d.17.B',3,'A mechanic checks the battery, cables, starter switch and starter relay of an engine start circuit. She is:','["guessing", "ignoring the starter", "inspecting an electrical starting system", "painting the starter"]'::jsonb,2,'Starter inspection.','original'),
('127.889.d.17.B',4,'During a starting system inspection, loose or corroded cable ends should be:','["greased only", "ignored", "painted", "cleaned and tightened"]'::jsonb,3,'Cable ends.','original'),
('127.889.d.17.C',3,'An engine won''t crank, so a mechanic uses a meter to follow voltage from the battery to the starter. She is:','["troubleshooting an electrical starting system", "ignoring the starter", "painting cables", "guessing"]'::jsonb,0,'Starter trouble.','original'),
('127.889.d.17.C',4,'If the starter solenoid clicks but the starter doesn''t turn, a good first check is the:','["oil color", "battery voltage under load", "seat track", "tire pressure"]'::jsonb,1,'Under load.','original'),
('127.889.d.17.D',3,'The engine won''t shut off with the key because the magneto switch circuit is faulty, so the mechanic tests the switch and the P-lead. She is:','["painting the switch", "guessing", "troubleshooting an ignition switch circuit", "ignoring the switch"]'::jsonb,2,'Switch circuit.','original'),
('127.889.d.17.D',4,'An ignition switch that does not ground the P-lead in the OFF position can leave the magneto:','["cool", "extra quiet", "safely off", "live and able to fire"]'::jsonb,3,'Open ground.','original'),
('127.889.d.17.E',3,'A mechanic matches an engine''s manufacturer chart to the correct spark plug part number and heat range. She is:','["identifying the correct spark plugs for replacement installation", "using any plug", "ignoring the chart", "guessing a plug"]'::jsonb,0,'Plug choice.','original'),
('127.889.d.17.E',4,'A spark plug heat range tells how well the plug:','["sounds", "carries heat away from its tip", "looks", "holds fuel"]'::jsonb,1,'Heat range.','original'),
('127.889.d.17.F',3,'A mechanic checks the turbine engine parts list to pick the right igniter plug for a combustor. She is:','["using a spark plug", "guessing", "identifying the correct igniter plug on a turbine engine", "ignoring the list"]'::jsonb,2,'Igniter plug.','original'),
('127.889.d.17.F',4,'A turbine igniter plug differs from a piston spark plug because it:','["needs no wire", "has no electrode", "uses oil", "has a surface-discharge design built for high energy"]'::jsonb,3,'Igniter design.','original'),
('127.889.d.18.A',3,'A student studies why too much fuel makes black smoke and too little makes a lean, hot engine. She is explaining:','["the purpose of proper fuel to air ratios and fuel metering", "describing seats", "describing tires", "ignoring ratios"]'::jsonb,0,'Fuel-air ratio.','original'),
('127.889.d.18.A',4,'A lean mixture can cause an engine to:','["run cold", "run hot and risk detonation", "never start", "make more oil"]'::jsonb,1,'Lean risk.','original'),
('127.889.d.18.B',3,'A student labels the throttle body, mixture control and metering jets of a fuel metering system. She is:','["labeling seats", "labeling tires", "identifying the components, basic operation and adjustment of fuel metering systems", "labeling lights"]'::jsonb,2,'Metering system.','original'),
('127.889.d.18.B',4,'Moving the mixture control toward lean:','["adds air", "stops the pump", "adds fuel", "reduces the fuel flow for the air entering the engine"]'::jsonb,3,'Mixture control.','original'),
('127.889.d.18.C',3,'A student traces fuel from the tank through a heater, lines, a pump, a valve and a filter. She is explaining:','["the purpose and basic operation of fuel heaters, lines, pumps, valves and filters", "describing tires", "avoiding fuel", "describing seats"]'::jsonb,0,'Fuel path.','original'),
('127.889.d.18.C',4,'A fuel heater on a turbine engine keeps:','["the pump quiet", "ice crystals from clogging the fuel filter", "the tank full", "fuel hot for burning"]'::jsonb,1,'Fuel heater.','original'),
('127.889.d.18.D',3,'A student explains how a nozzle sprays fuel in a fine mist and how a manifold feeds the nozzles. She is explaining:','["describing tires", "describing seats", "the basic operation of fuel nozzles and manifolds", "ignoring nozzles"]'::jsonb,2,'Nozzles.','original'),
