('127.889.d.18.J',3,'A mechanic is told that fuel on the skin or in the air is a fire and health hazard when handling fuel metering parts. She is researching:','["paint choices", "no risks", "the risks of handling fuel metering system components or fuel", "tire brands"]'::jsonb,2,'Handling fuel.','original'),
('127.889.d.18.J',4,'When handling fuel components, a mechanic should work:','["near sparks", "in a closed room", "near open flames", "in a ventilated area away from ignition sources"]'::jsonb,3,'Ventilation.','original'),
('127.889.d.18.K',3,'A student reads that opening fuel lines on a tank can spill fuel and release vapors. She is researching:','["the risks of fuel system maintenance", "tire brands", "paint choices", "no risks"]'::jsonb,0,'Fuel maintenance.','original'),
